-- =============================================================================
-- English Lab - V17: banco ampliado de los objetivos 10-12
-- Lleva PP (10), COND1 (11) y COND2 (12) de 10 a 100 actividades cada uno.
-- 90 filas nuevas por objetivo, ids explicitos 931-1200 (overriding system value).
-- level y skill son los del objetivo en V11 (B1/B1 y B2, grammar).
-- category_id: PP -> 2 (tiempos verbales), COND1/COND2 -> 6 (condicionales).
-- La clave sigue viviendo SOLO en el jsonb `content` (answer/accepted);
-- jamas viaja al navegador (el DTO de estudiante la omite).
-- Aprox. 60% MULTIPLE_CHOICE y 40% FILL_BLANK; sin prompts repetidos.
-- =============================================================================

-- Igual que en V13: en una base de pruebas reutilizada, filas autoincrementales
-- pueden ocupar el rango 931-1200 y romper la PK. Se liberan SOLO actividades de
-- prueba (objetivos fuera del seed 1-12); en produccion no borra nada.
delete from activities
where id between 931 and 1200
  and objective_id not between 1 and 12;

insert into activities (id, objective_id, type, level, skill, title, content, category_id) overriding system value values
